const listSegments = (dir) => {
  const out = [];
  for (const name of readdirSync(dir)) {
    const match = SEGMENT_RE.exec(name);
    if (match) out.push({ index: Number(m[1]), path: path.join(dir, name) });
  }
  out.sort((a, b) => a.index - b.index);
  return out;
