/**
 * Extract the committed, non-stale entries from a raw log buffer, using the
 * same bracket/fence rules as scanDirectory's recovery walk but without
 * touching any state: the incremental tail reader applies the result onto
 * the cached merged view. Returns:
 *   { units: [{entry}], watermark, closed, markerSeen }
 * `closed` is false when the buffer ends inside an uncommitted batch
 * bracket (a crash mid group): the caller must fall back to a healing full
 * scan instead of advancing its cursor. A truncate/compact marker
 * (`t`/`c`) or fence (`f`) likewise forces a full structural rescan.
 */
function committedUnits(raw, startWatermark) {
  const units = [];
  let watermark = startWatermark;
  let lineStart = 0;
  let group = null;
  let markerSeen = false;
  let fenceSeen = false;
  const epochOfEntry = (entry) =>
    entry !== null && typeof entry.g === 'number' ? entry.g : 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] !== 0x0a) continue;
    const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
    if (entry && entry.t === 'f') {
      if (epochOfEntry(entry) > watermark) watermark = epochOfEntry(entry);
      fenceSeen = true;
      group = null;
    } else if (group !== null) {
      const stale =
        entry !== null && typeof entry.g === 'number' && entry.g < watermark;
      if (entry && entry.t === 'bk' && entry.id === group.id && !stale) {
        for (const member of group.entries) units.push(member);
        group = null;
      } else if (entry && entry.t === 'b') {
        group = { id: entry.id, entries: [] };
      } else if (entry && !stale) {
        group.entries.push(entry);
      }
    } else if (entry && entry.t === 'b') {
      const stale = typeof entry.g === 'number' && entry.g < watermark;
      if (!stale) group = { id: entry.id, entries: [] };
    } else if (entry) {
      if (entry.t === 't' || entry.t === 'c') {
        markerSeen = true;
      } else if (!(typeof entry.g === 'number' && entry.g < watermark)) {
        units.push(entry);
      }
    }
    lineStart = i + 1;
  }
  return { units, watermark, closed: group === null, markerSeen, fenceSeen };
}

