    }
    nextSeq += 1;
    const id = randomUUID();
    const ack = { id, seq: nextSeq };
    acks.push(ack);
    if (key !== undefined) {
      owned.set(key, ack);
      fresh.set(key, ack);
    }
    let line = `{"t":"m","seq":${nextSeq},"id":${JSON.stringify(id)},"bytes":${size},"g":${lease.epoch}`;
