seq = nextSeq;
bytes += groupBytes;
usageBytes += groupBytes;
published += groupCount;
for (const [key, ack] of fresh) dedup.set(key, { id: ack.id, seq: ack.seq });
if (cursor) {
  cursor.off += wrote;
} else {
  try {
    const info = statSync(logPath);
    cursor = { dev: info.dev, ino: info.ino, off: info.size, watermark: fenceWatermark };
  } catch {
    cursor = null;
