// Adopt a full scan as the current cache and rebase the tail cursor on
// the active log's post-scan identity.
const adoptFullScan = (st) => {
  absorb(st);
  horizon = st.horizon;
  fenceWatermark = st.fenceEpoch;
  cursor = {
    dev: st.activeId.dev,
    ino: st.activeId.ino,
    off: st.activeId.size,
    watermark: st.fenceEpoch,
  };
};

// Read a slice [off, end) of a regular file synchronously.
const readTail = (file, off, length) => {
  const buf = Buffer.allocUnsafe(length);
  const fd = openSync(file, 'r');
  try {
    let got = 0;
    while (got < length) {
      const n = readSync(fd, buf, got, length - got, off + got);
      if (!Number.isInteger(n) || n <= 0) break;
      got += n;
    }
    return buf.subarray(0, got);
  } finally {
    closeSync(fd);
  }
};

// Apply committed tail units (m / s / p lines, fence-filtered) to the
// cache.
const applyUnits = (units) => {
  for (const entry of units) {
    if (entry.t === 'm') {
      if (entry.seq <= horizon) continue;
      seq = entry.seq;
      bytes += entry.bytes;
      usageBytes += entry.bytes;
      published += 1;
      if (typeof entry.d === 'string') {
        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
      }
    } else if (entry.t === 's') {
      replayed += entry.n;
    } else if (entry.t === 'p') {
      positions.set(entry.name, entry.pos);
    }
  }
};

/**
 * Bring the merged cache current without a full directory rescan. The
 * common case reads only the bytes appended to the active log since the
 * last look; a changed inode (truncate seal / compact reset / takeover
 * fence), a torn or uncommitted tail, or a structural marker escalates
 * to scanDirectory (+ healing when `mutating`).
 */
const catchupLocked = ({ mutating }) => {
  let info;
  try {
    info = statSync(logPath);
  } catch {
    info = { dev: 0, ino: 0, size: 0 };
  }
  if (
    cursor &&
    cursor.dev === info.dev &&
    cursor.ino === info.ino &&
    info.size >= cursor.off
  ) {
    if (info.size === cursor.off) return;
    const raw = readTail(logPath, cursor.off, info.size - cursor.off);
    const parsed = committedUnits(raw, cursor.watermark);
    if (parsed.closed && !parsed.structural) {
      applyUnits(parsed.units);
      cursor.off = info.size;
      cursor.watermark = parsed.watermark;
      fenceWatermark = Math.max(fenceWatermark, parsed.watermark);
      return;
    }
    // Open bracket / torn tail / marker in the new bytes: reconcile the
    // physical shape with a full scan. A read-only caller must not heal;
    // it leaves the cursor untouched so the next mutating job does.
    if (!mutating) {
      absorb(scanDirectory(dir));
      cursor = null;
      return;
    }
  }
  if (mutating) {
    adoptFullScan(prepareLocked(scanDirectory(dir)));
  } else {
    const st = scanDirectory(dir);
