      // keys with the acks the merged group actually assigned.
      const keyFirst = new Map();
      for (let i = 0; i < prepared.length; i++) {
        const key = prepared[i].dedupKey;
        if (key !== undefined && !keyFirst.has(key)) keyFirst.set(key, acks[i]);
