// Stage one publish/publishBatch request into the lock-free queue. The
// file is renamed into place before the mutex is taken, so whichever
// process drains next observes the request. Fsync follows the bus's own
// durability option: staging only needs to be visible to a concurrent
// process (rename + page cache), and a crashed caller's un-durable queue
// is reaped by heartbeat liveness on the next drain.
const stageRequest = (token, kind, items) => {
  const payload = JSON.stringify({
    v: 1,
    e: epoch,
    s: sessionId,
    k: kind,
    items: items.map((it) => {
      const part = { j: it.recordJson, z: it.size };
      if (it.dedupKey !== undefined) part.d = it.dedupKey;
      return part;
    }),
  });
  const tmp = qTmpPath(token);
  const fd = openSync(tmp, 'w');
  try {
    writeSync(fd, Buffer.from(payload, 'utf8'));
    if (fsync) fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
  renameSync(tmp, qPath(token));
};

