// Atomic write for pipeline handoff files. Cross-process visibility only
// needs the write + rename; fsync is added when the bus itself runs with
// fsync, so the default (no fsync) path pays no extra disk barriers.
const writePipelineFile = (file, tmpFile, contents) => {
  const fd = openSync(tmpFile, 'w');
  try {
    const buf = Buffer.from(contents, 'utf8');
    let off = 0;
    while (off < buf.length) off += writeSync(fd, buf, off, buf.length - off);
    if (fsync) fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
  renameSync(tmpFile, file);
};

