  if (r < 0.65) {
    jobs.push(procs[w].call('publish',{record:{w,i,k:'x'.repeat(i%7)}}).then(()=>{expected++;}));
  } else if (r < 0.85) {
    const recs = Array.from({length:1+(i%4)},(_,j)=>({w,i,j}));
