    jobs.push(procs[w].call('truncate',{before:Math.max(1,Math.floor(expected*0.3))}));
  } else {
    jobs.push(procs[w].call('compact'));
  }
  if (i%9===0) jobs.push(procs[w].call('replay',{from:0}));
